import { lineup, feed } from "stable.herd";
import { render } from "stable.ledger";

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var first = true;

    for pony in lineup() {
        let fed = feed(pony: pony, scoops: 3);

        if first {
            first = false;
        } else {
            io.write(text: ",")?;
        }

        io.write(text: render(fed))?;
    }

    return Ok(unit);
}

